import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true,args:['--use-gl=swiftshader']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:3000');
await page.locator('#playBtn').click();
await page.waitForTimeout(1500);
const started=await page.locator('#overlay').evaluate(e=>e.classList.contains('hidden'));
const initial={started,you:await page.locator('#youHp').textContent(),bot:await page.locator('#botHp').textContent(),timer:await page.locator('#timer').textContent()};
await page.mouse.move(1050,500);
await page.keyboard.down('Space');
await page.waitForTimeout(5000);
await page.keyboard.up('Space');
const afterFire={you:await page.locator('#youHp').textContent(),bot:await page.locator('#botHp').textContent()};
await page.keyboard.press('Shift');
const dashToast=await page.locator('#toast').textContent();
await page.keyboard.press('e');
const pulseToast=await page.locator('#toast').textContent();
const pulseCd=await page.locator('#pulseCd').textContent();
console.log(JSON.stringify({initial,afterFire,dashToast,pulseToast,pulseCd,errors}));
await page.screenshot({path:'/tmp/opencode/neon-rift-active.png'});
await browser.close();

