import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true,args:['--use-gl=swiftshader']});
const context = await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
const page = await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:3000');
await page.locator('#playBtn').tap();
await page.waitForTimeout(500);
const mobileStart={overlayHidden:await page.locator('#overlay').evaluate(e=>e.classList.contains('hidden')),controlsVisible:await page.locator('#mobileControls').isVisible(), hp:await page.locator('#botHp').textContent()};
// Mobile aim through a touch pointer move, then hold the fire control.
await page.evaluate(()=>window.dispatchEvent(new PointerEvent('pointermove',{pointerType:'touch',clientX:300,clientY:490,bubbles:true})));
await page.locator('#fireBtn').evaluate(el=>el.dispatchEvent(new PointerEvent('pointerdown',{pointerId:7,pointerType:'touch',clientX:el.getBoundingClientRect().x+20,clientY:el.getBoundingClientRect().y+20,bubbles:true,cancelable:true})));
await page.waitForTimeout(4000);
await page.locator('#fireBtn').evaluate(el=>el.dispatchEvent(new PointerEvent('pointerup',{pointerId:7,pointerType:'touch',bubbles:true})));
const afterMobileFire={botHp:await page.locator('#botHp').textContent(),youHp:await page.locator('#youHp').textContent()};
await page.locator('#dashBtn').tap();
const dashToast=await page.locator('#toast').textContent();
await page.locator('#pulseBtn').tap();
const pulseToast=await page.locator('#toast').textContent();
// Progress the round clock quickly via normal gameplay's visible timer using repeated frame pauses is impractical;
// test round transition by winning through sustained fire aimed at the opponent.
for(let i=0;i<8;i++){
  await page.evaluate((x)=>window.dispatchEvent(new PointerEvent('pointermove',{pointerType:'touch',clientX:x,clientY:490,bubbles:true})),290+i*4);
  await page.locator('#fireBtn').evaluate(el=>el.dispatchEvent(new PointerEvent('pointerdown',{pointerId:9,pointerType:'touch',bubbles:true,cancelable:true})));
  await page.waitForTimeout(7000);
  await page.locator('#fireBtn').evaluate(el=>el.dispatchEvent(new PointerEvent('pointerup',{pointerId:9,pointerType:'touch',bubbles:true})));
  if(await page.locator('#overlay').evaluate(e=>!e.classList.contains('hidden'))) break;
}
const roundEnd={overlayHidden:await page.locator('#overlay').evaluate(e=>e.classList.contains('hidden')), title:await page.locator('#overlayTitle').innerText(),scoreYou:await page.locator('#scoreYou').textContent(),scoreBot:await page.locator('#scoreBot').textContent(), round:await page.locator('#roundNo').textContent()};
console.log(JSON.stringify({mobileStart,afterMobileFire,dashToast,pulseToast,roundEnd,errors}));
await page.screenshot({path:'/tmp/opencode/neon-rift-mobile.png'});
await browser.close();

